advanced.custom_css:
/* Just Herbs cart drawer — cartx Custom CSS
   Source design: Figma "Just Herbs" (section "Cart", node 19:19924), mobile.
   Written for the live cartx drawer (no new app settings needed).
   Embedded in justherbs-cart-settings.json (advanced.custom_css). Edit here,
   then rebuild the JSON, or paste into Customize Cart → Custom CSS. */

#cartmax-root .cartmax-drawer {
  --jh-ink: #1A1A1A;
  --jh-muted: #666666;
  --jh-green: #358C58;
  --jh-green-dark: #084121;
  --jh-mint: #EBF3EE;
  --jh-pink: #F9105E;
  --jh-red: #CC3434;
  --jh-line: rgba(0, 19, 37, 0.08);
  color: var(--jh-ink);
}

/* Header: "Cart" + red count badge */
#cartmax-root .cartmax-header {
  min-height: 60px;
  padding: 8px 24px;
  border-bottom: 0;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.059);
  position: relative;
  z-index: 1;
}
#cartmax-root .cartmax-title {
  gap: 4px;
  font-size: 24px;
  font-weight: 500;
  line-height: 24px;
}
#cartmax-root .cartmax-header-count {
  width: 20px;
  height: 20px;
  background: #D92727;
  color: #F1F1F1;
  font-size: 14px;
  font-weight: 500;
  line-height: 14px;
}
#cartmax-root .cartmax-close {
  background: none;
  color: var(--jh-ink);
}

/* Milestones: mint band, rounded track, gift-box icons */
#cartmax-root .cartmax-progress {
  padding: 6px 32px 4px;
  border-bottom: 0;
  background: var(--jh-mint);
}
#cartmax-root .cartmax-progress-msg-wrap { margin: 0 0 4px; }
#cartmax-root .cartmax-progress-msg {
  margin: 0 auto;
  padding: 0;
  border: 0;
  background: none;
  color: #1C1B17;
  font-size: 12px;
  font-weight: 600;
  line-height: 19px;
  letter-spacing: 0;
}
#cartmax-root .cartmax-progress-track {
  height: 10px;
  margin-top: 30px;
  margin-bottom: 52px;
  border: 0.5px solid #8F8F8F;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.8);
}
#cartmax-root .cartmax-progress-fill {
  border-radius: 10px;
  background: var(--jh-green);
}
#cartmax-root .cartmax-milestone .cartmax-milestone-dot {
  width: 34px;
  height: 40px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
#cartmax-root .cartmax-milestone .cartmax-milestone-dot { margin-top: -18px; }
#cartmax-root .cartmax-milestone-label {
  top: 22px;
  max-width: 90px;
  color: #1C1B17;
  letter-spacing: 0;
}
#cartmax-root .cartmax-milestone .cartmax-milestone-label-main {
  color: #1C1B17;
  font-size: 10px;
  font-weight: 600;
  line-height: 10px;
}
#cartmax-root .cartmax-milestone .cartmax-milestone-sub-label {
  margin-top: 2px;
  color: #1C1B17;
  font-size: 14px;
  font-weight: 600;
  line-height: 13px;
  letter-spacing: 0;
}

/* Cart items: bordered cards */
#cartmax-root .cartmax-line-item {
  gap: 12px;
  margin: 12px 16px 0;
  padding: 10px;
  border: 1px solid var(--jh-line);
  border-radius: 8px;
}
#cartmax-root .cartmax-line-image {
  width: 60px;
  height: 60px;
  border: 1px solid #909090;
  border-radius: 4px;
}
#cartmax-root .cartmax-line-details { gap: 4px; }
#cartmax-root .cartmax-line-title {
  color: var(--jh-ink);
  font-size: 14px;
  font-weight: 500;
  line-height: 21px;
}
#cartmax-root .cartmax-line-price {
  gap: 6px;
  color: var(--jh-ink);
  font-size: 16px;
  font-weight: 600;
  line-height: 16px;
}
#cartmax-root .cartmax-line-price-original {
  color: #999999;
  font-size: 12px;
  font-weight: 400;
}
#cartmax-root .cartmax-line-savings-badge {
  color: var(--jh-red);
  font-size: 11px;
  text-transform: capitalize;
}
#cartmax-root .cartmax-line-savings-badge svg { display: none !important; }
#cartmax-root .cartmax-variant-pill {
  padding: 4px 8px;
  border: 1px solid var(--jh-line);
  border-radius: 8px;
  color: var(--jh-muted);
  font-size: 12px;
  line-height: 18px;
}
#cartmax-root .cartmax-qty-controls {
  height: 32px;
  border: 0;
}
#cartmax-root .cartmax-qty-btn {
  width: 32px;
  height: 32px;
  color: var(--jh-ink);
}
#cartmax-root .cartmax-qty-value {
  border: 0;
  font-size: 14px;
  font-weight: 500;
  line-height: 32px;
}
#cartmax-root .cartmax-line-discount-tag {
  border-color: rgba(40, 110, 68, 0.2);
  background: var(--jh-mint);
  color: var(--jh-green-dark);
}

/* Free gift line: mint card, gift sticker, "Free Gift" */
#cartmax-root .cartmax-line-item.cartmax-line-freebie {
  overflow: visible;
  content-visibility: visible;
  border-color: rgba(40, 110, 68, 0.12);
  background: var(--jh-mint);
}
