#cartmax-root .cartmax-line-freebie .cartmax-line-image {
  width: 46px;
  height: 46px;
}
#cartmax-root .cartmax-line-freebie .cartmax-gift-badge {
  padding: 0;
  background: none;
  font-size: 0;
}
#cartmax-root .cartmax-line-freebie .cartmax-gift-badge::after {
  content: "Free Gift";
  color: #2D784B;
  font-size: 16px;
  font-weight: 700;
  line-height: 16px;
  letter-spacing: 0;
  text-transform: none;
}

/* Coupons: code input row + View all; suggested cards live in the panel */
#cartmax-root .cartmax-coupons { padding: 12px 16px 0; }
#cartmax-root .cartmax-discount-block {
  padding: 0;
  border: 0;
  background: none;
}
#cartmax-root .cartmax-discount-input-row {
  min-height: 57px;
