}
#cartmax-root .cartmax-discount-input {
  padding-left: 4px;
  color: var(--jh-ink);
}
#cartmax-root .cartmax-discount-input::placeholder {
  color: var(--jh-green);
  font-weight: 700;
}
#cartmax-root .cartmax-discount-divider { background: var(--jh-line); }
#cartmax-root .cartmax-discount-viewall {
  color: var(--jh-green);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0;
}
#cartmax-root .cartmax-coupons .cartmax-discount-cards { display: none; }

/* Applied coupon: ticket card with Remove */
#cartmax-root .cartmax-applied-chips { margin-top: 8px; }
#cartmax-root .cartmax-applied-chip {
  position: relative;
  width: 100%;
  min-height: 52px;
  justify-content: space-between;
  padding: 8px 16px;
  overflow: hidden;
  border: 0;
  border-radius: 8px;
  background: linear-gradient(90deg, #F8F8EE 0%, #AAD9B2 100%);
}
#cartmax-root .cartmax-applied-chip::before,
#cartmax-root .cartmax-applied-chip::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 20px;
  height: 20px;
  margin-top: -10px;
  border-radius: 50%;
  background: #FFFFFF;
}
#cartmax-root .cartmax-applied-chip::before { left: -10px; }
#cartmax-root .cartmax-applied-chip::after { right: -10px; }
#cartmax-root .cartmax-applied-chip-check { display: none; }
#cartmax-root .cartmax-applied-chip-code {
  flex: 1;
  color: var(--jh-ink);
  font-size: 14px;
  font-weight: 700;
  line-height: 20px;
  letter-spacing: 2px;
  text-transform: uppercase;
}
#cartmax-root .cartmax-applied-chip-remove {
  width: auto;
  height: auto;
  padding: 0 4px;
  border-radius: 0;
  font-size: 0;
}
#cartmax-root .cartmax-applied-chip-remove svg { display: none; }
#cartmax-root .cartmax-applied-chip-remove::after {
  content: "Remove";
  color: var(--jh-green-dark);
  font-size: 14px;
  font-weight: 600;
}
#cartmax-root .cartmax-applied-chip-remove:hover { background: none; }

/* Recommendations: "Special price" pink block */
#cartmax-root .cartmax-upsells {
  margin: 12px 16px;
  padding: 8px 12px 12px;
  border: 1px solid rgba(40, 110, 68, 0.08);
  border-radius: 12px;
  background: #FECBDC;
}
#cartmax-root .cartmax-upsells-heading {
  flex-direction: column;
  align-items: center;
  gap: 4px;
  margin-bottom: 12px;
  color: var(--jh-ink);
  font-size: 16px;
  font-weight: 600;
  line-height: 21px;
}
