#cartmax-root .cartmax-upsells-scroll {
  gap: 8px;
  margin-left: -12px;
  margin-right: -12px;
  padding-left: 12px;
  padding-right: 12px;
  scroll-padding-left: 12px;
}
#cartmax-root .cartmax-upsell-card {
  position: relative;
  width: 282px;
  gap: 10px;
  padding: 4px 8px;
  border: 0;
  border-radius: 8px;
  background: #FFFFFF;
}
#cartmax-root .cartmax-upsell-img,
#cartmax-root .cartmax-upsell-img-placeholder {
  width: 64px;
  height: 64px;
  border-radius: 8px;
}
#cartmax-root .cartmax-upsell-info {
  gap: 3px;
  padding-right: 62px;
}
#cartmax-root .cartmax-upsell-title {
  color: #1B1B1B;
  font-size: 12px;
  font-weight: 500;
  line-height: 15px;
}
#cartmax-root .cartmax-upsell-price { gap: 4px; }
#cartmax-root .cartmax-upsell-sale {
  padding: 2px 6px;
  border: 1px solid #FFFFFF;
  border-radius: 50px;
  background: var(--jh-pink);
  box-shadow: 1px 1px 0 var(--jh-pink);
  color: #F1F1F1;
  font-size: 13px;
  font-weight: 600;
  line-height: 14px;
}
#cartmax-root .cartmax-upsell-compare {
  color: #999999;
  font-size: 11px;
}
#cartmax-root .cartmax-upsell-add,
#cartmax-root .cartmax-upsell-add:hover:not(:disabled) {
  position: absolute;
  right: 8px;
  top: 50%;
  width: 54px;
  height: 34px;
  margin: -17px 0 0;
  padding: 0;
  border: 1px solid var(--jh-green-dark);
  border-radius: 8px 3px 8px 3px;
  background: var(--jh-green);
  box-shadow: 1px 1px 0 var(--jh-green-dark);
  color: #FFFFFF;
  font-size: 13px;
  font-weight: 500;
  text-transform: none;
}

/* Savings strip */
#cartmax-root .cartmax-footer { box-shadow: none; }
#cartmax-root .cartmax-footer-savings {
  gap: 4px;
  padding: 2px 16px;
  font-size: 12px;
  font-weight: 400;
  line-height: 20px;
  box-shadow: 8px 0 10px rgba(0, 0, 0, 0.1);
}
#cartmax-root .cartmax-footer-savings-icon { display: none; }
#cartmax-root .cartmax-footer-savings-amount { font-size: 13px; font-weight: 600; }

/* Checkout bar: total, "View details", green button with UPI line */
#cartmax-root .cartmax-footer-checkout {
  gap: 12px;
  padding: 8px 16px 16px;
}
#cartmax-root .cartmax-footer-price { gap: 0; }
#cartmax-root .cartmax-footer-price-amount {
  color: var(--jh-ink);
  font-size: 20px;
  font-weight: 700;
  line-height: 30px;
}
#cartmax-root .cartmax-price-breakup-link {
  color: var(--jh-ink);
  font-size: 0;
  text-decoration: none;
}
#cartmax-root .cartmax-price-breakup-link::after {
  content: "View details";
  font-size: 12px;
  font-weight: 500;
  line-height: 18px;
  letter-spacing: 0;
  text-transform: none;
  text-decoration: underline;
}
#cartmax-root .cartmax-checkout-btn,
#cartmax-root .cartmax-checkout-btn:hover {
  flex: 1;
  justify-content: space-between;
  height: 48px;
  padding: 7px 20px;
  border-radius: 6px;
  letter-spacing: 0;
  text-transform: none;
}
#cartmax-root .cartmax-checkout-btn .cartmax-checkout-label {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  font-size: 16px;
  font-weight: 600;
  line-height: 16px;
  letter-spacing: 0;
  text-transform: none;
}
#cartmax-root .cartmax-checkout-btn .cartmax-checkout-label::after {
  content: "Extra 5% OFF on UPI";
  font-size: 10px;
  font-weight: 400;
  line-height: 10px;
}

/* Offers & Coupons panel */
#cartmax-root .cartmax-offers-panel-header {
  position: relative;
  justify-content: center;
  min-height: 60px;
  padding: 10px 32px;
  border-bottom: 0;
}
#cartmax-root .cartmax-offers-back {
  position: absolute;
  left: 24px;
  background: none;
  color: #18181B;
}
#cartmax-root .cartmax-offers-title {
  color: var(--jh-ink);
  font-size: 18px;
  font-weight: 500;
  line-height: 24px;
}
#cartmax-root .cartmax-offers-body { gap: 12px; padding: 12px 16px; }
#cartmax-root .cartmax-offers-label {
  color: #18181B;
  font-size: 0;
  letter-spacing: 0;
  text-transform: none;
}
#cartmax-root .cartmax-offers-label::after {
  content: "All Coupons";
  font-size: 16px;
  font-weight: 600;
  line-height: 24px;
}
#cartmax-root .cartmax-offers-card {
  height: auto;
  min-height: 56px;
  gap: 4px;
  padding: 8px 12px;
  border: 1px solid #9F9FA9;
  border-radius: 6px;
}
#cartmax-root .cartmax-offers-card-accent {
  width: 44px;
  height: auto;
  padding: 0;
  background: none;
}
#cartmax-root .cartmax-offers-card-accent span {
  color: var(--jh-green-dark);
  font-size: 13px;
  font-weight: 700;
  line-height: 16px;
  letter-spacing: 0;
  text-align: center;
  white-space: normal;
  writing-mode: horizontal-tb;
  transform: none;
}
#cartmax-root .cartmax-offers-card-info {
  align-self: stretch;
  justify-content: center;
  gap: 4px;
  padding: 0 8px;
  border-radius: 3px;
  background: #FAFAFA;
}
#cartmax-root .cartmax-offers-card-code {
  color: var(--jh-ink);
  font-size: 14px;
  font-weight: 700;
  line-height: 20px;
  letter-spacing: 2px;
  text-transform: uppercase;
}
#cartmax-root .cartmax-offers-card-savings {
  color: #1A4D00;
  font-size: 11px;
  line-height: 16px;
}
#cartmax-root .cartmax-offers-card-btn {
  width: 67px;
  height: 40px;
  margin: 0;
  border: 1px solid var(--jh-green-dark);
  border-radius: 8px 3px 8px 3px;
  background: var(--jh-green);
  box-shadow: 1px 1px 0 var(--jh-green-dark);
  color: #FFFFFF;
  font-size: 13px;
  font-weight: 500;
}

/* Price breakup */
#cartmax-root .cartmax-pb-backdrop { background: rgba(0, 0, 0, 0.25); }
#cartmax-root .cartmax-price-breakup-header {
  padding: 8px 16px;
  min-height: 56px;
  color: #18181B;
  font-size: 18px;
  font-weight: 700;
  line-height: 26px;
}
#cartmax-root .cartmax-price-breakup-close { background: none; }
#cartmax-root .cartmax-pb-divider { background: #D4D4D8; }
#cartmax-root .cartmax-price-breakup-rows { padding: 24px 16px; }
#cartmax-root .cartmax-pb-label {
  color: #52525C;
  font-weight: 500;
  line-height: 20px;
}
#cartmax-root .cartmax-pb-amount { color: #18181B; }
#cartmax-root .cartmax-pb-amount.cartmax-pb-discount { color: #008236; }
#cartmax-root .cartmax-pb-amount.cartmax-pb-shipping { color: #E20019; }
/* Shipping rules box (static text, placeholder until the client confirms) */
#cartmax-root .cartmax-price-breakup-rows::after {
  content: "Prepaid Orders\A ₹79–₹398.99 → Shipping ₹49\A ₹399 & above → Free Shipping 🎉\A\A Cash on Delivery (COD)\A ₹399–₹698.99 → Shipping ₹99\A ₹699–₹1,990 → Shipping ₹49";
  padding: 16px;
  border-radius: 6px;
  background: #F4F4F5;
  color: #52525C;
  font-size: 14px;
  line-height: 20px;
  white-space: pre-line;
}
#cartmax-root .cartmax-price-breakup-total {
  padding: 20px 16px;
  border: 1px solid #E4E4E7;
  color: #18181B;
  font-weight: 700;
}
